/* UpsNewbillingMapper.updateCustomsInfo : updateCustomsInfo Update */
	UPDATE TB_ECM_OD SET
		   CUSTOMS_ID_TYPE = #{CUSTOMS_ID_TYPE}


		  ,CUSTOMS_ID_ENC = dbo.Cryptography(OD_JOB_NO, #{CUSTOMS_ID}, 0)


		  ,CUSTOMS_ID = #{CUSTOMS_ID}


	WHERE OD_JOB_NO = #{odJobNo};
	UPDATE TB_ECM_OD_ADDITIONAL SET
		   LC_NO = #{LC_NO}
	WHERE OD_JOB_NO = #{odJobNo};

mapper.select:
/* UpsNewbillingMapper.selecteCISProgramCreate : UPS selecteCISProgramCreate 조회 */ SELECT mod.MBL_NO ,CONVERT(VARCHAR(8), mod.AR_DATE, 112) AS AR_DATE ,mod.LINE_CODE ,mod.VESSEL_FLIGHT ,mod.MRN ,mod.MSN ,mod.DEST_CODE ,od.HSN ,od.HBL_NO ,od.SHIPPER_NAME ,od.CURRENCY_CODE ,od.ASSIGNMENT_WH_CODE ,ISNULL(od.PIECES, 0) AS pieces ,FORMAT(ISNULL(od.AMOUNT_CUR, 0), '#,##0.0000') AS AMOUNT_CUR ,FORMAT(ISNULL(od.GWT, 0), '#,##0.000') AS GWT ,ad.ORIG ,ad.BILLING_TERM ,ad.TRANS_TYPE ,ad.DUTIES FROM TB_ECM_OD mod INNER JOIN TB_ECM_OD od ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO AND od.BL_TYPE_MH = 'H' INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
AND ISNULL(ad.SIMPLE_DOC_NO, '') IN(#{item})
WHERE mod.OD_JOB_NO IN(#{item})
WHERE mod.OD_JOB_NO = #{masterOdJobNo}
AND od.OD_JOB_NO IN(#{item.odJobNo})

