/* UpsNewbillingMapper.WaybillExceptHot : WaybillExceptHot 업데이트 */
UPDATE
		WaybillExceptHot
   SET
		LowToHigh = #{lowToHigh}
 WHERE
		ShipmentNumber = #{hblNo}

/* UpsNewbillingMapper.updatePerrorWaybillMFCSDN : WaybillMFCSDN 업데이트 */
UPDATE
		WaybillMFCSDN
   SET
		Perror = #{Perror}
		,PerrorNumber = #{customsId}
 WHERE
		ShipmentNumber = #{hblNo}

/* UpsNewbillingMapper.updateCustomsIdOd : 개인통관부호 초기화 */ UPDATE TB_ECM_OD SET
CUSTOMS_ID_ENC = ''
CUSTOMS_ID = ''
WHERE OD_JOB_NO = #{odJobNo}

/* UpsNewbillingMapper.updateDeliveryNoteOd : 개인통관부호 저장 */ UPDATE TB_ECM_OD SET
DELIVERY_NOTE = CUSTOMS_ID_ENC
DELIVERY_NOTE = CUSTOMS_ID
WHERE OD_JOB_NO = #{odJobNo}

